expected = {
    "order_id": "int64",
    "amount": "float64",
    "status": "object",
}

def enforce_schema(df):
    actual = {c: str(t) for c, t in df.dtypes.items()}
    missing = set(expected) - set(actual)
    changed = {c: (expected[c], actual[c])
               for c in expected if c in actual and actual[c] != expected[c]}
    if missing or changed:
        raise SchemaError(f"missing={missing} changed={changed}")
    return df
